(async()=>{const status=document.getElementById('downloads-status');try{const r=await fetch('./release.json',{cache:'no-store'});if(!r.ok)throw new Error('manifest');const d=await r.json();for(const k of ['windows','android']){const a=d[k];if(!a||!/^([a-f0-9]{64})$/.test(String(a.sha256||''))||!/^[A-Za-z0-9._-]+\.(exe|apk)$/i.test(a.file))throw new Error('manifest');document.querySelector('[data-hash="'+k+'"]').textContent=a.sha256;}status.textContent='Archivos publicados. Puedes comprobar su huella SHA-256 antes de instalarlos.';}catch{status.textContent='Si la descarga no está disponible, esta publicación todavía no ha terminado. Consulta las compilaciones en GitHub.';status.style.color='#eac16c';}})();